<template>
  <div ref="root" class="furnace" :class="[`is-${heat}`, { 'is-offline': offline, 'is-failed': failed }]">
    <svg viewBox="0 0 500 490" aria-label="圆腹三足丹炉">
      <defs><linearGradient id="copper" x1="0" x2="1"><stop stop-color="var(--deep)"/><stop offset=".43" stop-color="var(--gold)"/><stop offset=".7" stop-color="var(--bright)"/><stop offset="1" stop-color="var(--deep)"/></linearGradient><radialGradient id="flame" cx="50%" cy="82%"><stop stop-color="var(--bright)"/><stop offset=".42" stop-color="var(--fire)"/><stop offset="1" stop-color="var(--deep)"/></radialGradient><filter id="metal"><feTurbulence type="fractalNoise" baseFrequency=".04" numOctaves="2" result="n"/><feColorMatrix in="n" values=".5 0 0 0 .25 .5 0 0 0 .18 .5 0 0 0 .08 0 0 0 .10 0" result="grain"/><feComposite in="grain" in2="SourceGraphic" operator="in" result="t"/><feBlend in="SourceGraphic" in2="t" mode="multiply"/></filter><filter id="blur"><feGaussianBlur stdDeviation="10"/></filter></defs>
      <ellipse class="floor" cx="250" cy="436" rx="150" ry="34"/>
      <g class="flames"><path class="outer" d="M134 410 C109 355 159 335 167 278 C206 322 194 355 217 373 C209 303 263 264 276 195 C332 275 306 332 356 410 Z"/><path class="middle" d="M167 412 C150 364 203 329 201 286 C244 332 231 363 250 382 C257 327 298 297 299 243 C340 318 324 368 339 412 Z"/><path class="core" d="M205 412 C198 373 232 345 242 314 C270 345 258 375 274 390 C280 351 310 331 309 290 C337 356 319 388 323 412 Z"/></g>
      <g class="body" filter="url(#metal)"><path class="leg" d="M165 347 Q145 390 140 432 Q161 439 185 430 L211 360"/><path class="leg" d="M335 347 Q355 390 360 432 Q339 439 315 430 L289 360"/><path class="leg" d="M235 366 Q244 409 250 442 Q256 409 265 366"/><path class="ear" d="M132 216 Q89 197 103 164 Q122 149 151 183"/><path class="ear" d="M368 216 Q411 197 397 164 Q378 149 349 183"/><path class="belly" d="M126 202 Q130 151 250 148 Q370 151 374 202 L360 323 Q351 382 250 387 Q149 382 140 323 Z"/><ellipse class="rim" cx="250" cy="201" rx="126" ry="35"/><ellipse class="opening" cx="250" cy="199" rx="96" ry="21"/><path class="lid" d="M151 190 Q162 105 250 92 Q338 105 349 190 Q303 205 250 204 Q197 205 151 190 Z"/><circle class="pearl" cx="250" cy="90" r="18"/><text class="dan" x="250" y="294">丹</text></g>
      <circle ref="elixir" class="elixir" cx="250" cy="198" r="24"/><circle ref="flash" class="flash" cx="308" cy="45" r="38"/><path id="elixir-path" d="M250 198 C318 151 350 85 308 45" fill="none"/>
      <g class="smoke"><path d="M203 159 C170 115 218 99 198 53"/><path d="M296 159 C326 118 280 93 302 50"/></g>
    </svg><i v-for="n in sparks" :key="n" class="spark" :style="{ '--i': n }"/>
  </div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { gsap } from 'gsap'
import { MotionPathPlugin } from 'gsap/MotionPathPlugin'
import type { AlchemyHeat, AlchemyVisualConfig } from '../../config/alchemy-stage'
gsap.registerPlugin(MotionPathPlugin)
const props = defineProps<{ config: AlchemyVisualConfig; heat: AlchemyHeat; offline?: boolean; failed?: boolean }>()
const root = ref<HTMLElement>(); const elixir = ref<SVGCircleElement>(); const flash = ref<SVGCircleElement>(); const sparks = computed(() => props.heat === 'fierce' ? Math.min(12, props.config.particleCount + 3) : props.heat === 'complete' ? Math.min(6, props.config.particleCount) : Math.min(4, props.config.particleCount)); let ctx: gsap.Context | undefined
const animate = () => { ctx?.revert(); ctx = gsap.context(() => { const fierce = props.heat === 'fierce'; gsap.to('.flames', { scaleY: fierce ? 1.2 : props.heat === 'complete' ? .72 : .86, scaleX: fierce ? 1.12 : 1, duration: props.config.flameSpeed * (fierce ? .52 : 1), transformOrigin: '50% 100%', repeat: -1, yoyo: true, ease: 'sine.inOut' }); gsap.to('.floor', { opacity: fierce ? .55 : .28, scaleX: fierce ? 1.18 : 1, transformOrigin: '50% 50%', duration: props.config.breathSeconds, repeat: -1, yoyo: true, ease: 'sine.inOut' }); }, root.value) }
const releaseElixir = () => new Promise<void>(resolve => { if (!elixir.value || !flash.value) return resolve(); const tl = gsap.timeline({ onComplete: resolve }); tl.to('.lid', { y: -6, rotation: -3, duration: .08, yoyo: true, repeat: 2, transformOrigin: '50% 100%' }).set(elixir.value, { opacity: 1, scale: .35, transformOrigin: '50% 50%' }).to(elixir.value, { scale: 1.18, duration: .1 }).to(elixir.value, { duration: .22, motionPath: { path: '#elixir-path', align: '#elixir-path' }, ease: 'power2.inOut' }).set(flash.value, { opacity: .46, scale: .2, transformOrigin: '50% 50%' }, '-=.03').to(flash.value, { opacity: 0, scale: 2.4, duration: .13 }).to(elixir.value, { opacity: 0, scale: .2, duration: .1 }, '<') })
watch(() => [props.heat, props.config.flameSpeed, props.config.breathSeconds], animate); onMounted(animate); onBeforeUnmount(() => ctx?.revert()); defineExpose({ releaseElixir })
</script>
<style scoped>
.furnace{position:relative;width:min(540px,67vw);aspect-ratio:1;--gold:var(--alchemy-gold);--bright:var(--alchemy-gold-bright);--fire:var(--alchemy-fire);--deep:var(--alchemy-fire-deep);filter:drop-shadow(0 16px 20px rgba(0,0,0,.3))}.furnace svg{width:100%;height:100%;overflow:visible}.floor{fill:var(--alchemy-reflection);opacity:.3;filter:url(#blur)}.flames{transform-box:fill-box}.flames path{fill:url(#flame)}.outer{opacity:.7}.middle{opacity:.92}.core{fill:var(--bright)!important}.body>*{stroke:url(#copper);stroke-width:6;stroke-linejoin:round}.belly,.lid,.leg,.ear{fill:#332013}.rim{fill:#4a2a12}.opening{fill:#110b08;stroke-width:3}.pearl{fill:var(--bright)}.dan{fill:var(--gold);font-family:serif;font-size:76px;font-weight:700;text-anchor:middle;opacity:.22}.smoke{fill:none;stroke:var(--alchemy-ink);stroke-width:2;opacity:.11}.elixir{opacity:0;fill:var(--bright);stroke:var(--gold);stroke-width:6;filter:drop-shadow(0 0 15px var(--gold))}.flash{opacity:0;fill:var(--bright);filter:blur(3px)}.spark{position:absolute;left:calc(30% + (var(--i) * 5%));bottom:21%;width:4px;height:4px;border-radius:50%;background:var(--bright);animation:spark 1.4s calc(var(--i)*-.16s) infinite ease-out}.is-offline .flames{filter:hue-rotate(145deg) saturate(.6);opacity:.48}.is-failed .lid{transform:rotate(8deg);transform-origin:50% 100%}.is-failed .flames{opacity:.13}@keyframes spark{from{opacity:0;transform:translateY(0)}25%{opacity:.9}to{opacity:0;transform:translateY(-76px) translateX(15px)}}
</style>
